package main
import("fmt";"math";"sort")
const history_w=2*math.Pi*4124/(1<<20)
type history_interval struct{First int `json:"first"`;End int `json:"end_exclusive"`}
type history_fit struct{First int `json:"first"`;End int `json:"end_exclusive"`;Beta [3]float64 `json:"cos_sin_dc"`;Amplitude float64 `json:"amplitude_pcm"`;Phase *float64 `json:"phase_cos_sin_radians"`;RMS float64 `json:"training_residual_rms_pcm"`}
func history_basis(n int)[3]float64{return [3]float64{math.Cos(history_w*float64(n)),math.Sin(history_w*float64(n)),1}}
func history_predict(f history_fit,n int)float64{x:=history_basis(n);return x[0]*f.Beta[0]+x[1]*f.Beta[1]+f.Beta[2]}
func history_fit_fixed(v []float64,first,end int)(history_fit,error){f:=history_fit{First:first,End:end};if first<0||end>len(v)||end-first<3{return f,fmt.Errorf("fixed fit bounds")};constant:=true;var a [3][4]float64;for n:=first;n<end;n++{if v[n]!=v[first]{constant=false};x:=history_basis(n);for i:=0;i<3;i++{for j:=0;j<3;j++{a[i][j]+=x[i]*x[j]};a[i][3]+=x[i]*v[n]}};if constant{f.Beta[2]=v[first];return f,nil};for k:=0;k<3;k++{p:=k;for i:=k+1;i<3;i++{if math.Abs(a[i][k])>math.Abs(a[p][k]){p=i}};if math.Abs(a[p][k])<1e-12{return f,fmt.Errorf("singular fixed basis")};a[k],a[p]=a[p],a[k];scale:=a[k][k];for j:=k;j<4;j++{a[k][j]/=scale};for i:=0;i<3;i++{if i==k{continue};scale=a[i][k];for j:=k;j<4;j++{a[i][j]-=scale*a[k][j]}}};for i:=0;i<3;i++{f.Beta[i]=a[i][3]};f.Amplitude=math.Hypot(f.Beta[0],f.Beta[1]);if f.Amplitude>0{phase:=math.Atan2(f.Beta[1],f.Beta[0]);f.Phase=&phase};sum:=0.;for n:=first;n<end;n++{e:=v[n]-history_predict(f,n);sum+=e*e};f.RMS=math.Sqrt(sum/float64(end-first));return f,nil}
func history_stats(v []float64,first,end int)map[string]interface{}{lo,hi:=v[first],v[first];sum,square:=0.,0.;zeros,jumps:=0,0;for n:=first;n<end;n++{x:=v[n];lo=math.Min(lo,x);hi=math.Max(hi,x);sum+=x;square+=x*x;if x==0{zeros++};if n>first&&math.Abs(x-v[n-1])>=4096{jumps++}};return map[string]interface{}{"first":first,"end_exclusive":end,"samples":end-first,"min_pcm":lo,"max_pcm":hi,"mean_pcm":sum/float64(end-first),"rms_pcm":math.Sqrt(square/float64(end-first)),"exact_zero_count":zeros,"adjacent_jumps_at_least4096_pcm":jumps}}
func history_residual(v []float64,first,end int,f history_fit)map[string]interface{}{sum,square,peak:=0.,0.,0.;for n:=first;n<end;n++{e:=v[n]-history_predict(f,n);sum+=e;square+=e*e;peak=math.Max(peak,math.Abs(e))};rms:=math.Sqrt(square/float64(end-first));var relative *float64;if f.Amplitude>0{x:=rms/f.Amplitude;relative=&x};return map[string]interface{}{"first":first,"end_exclusive":end,"samples":end-first,"rms_pcm":rms,"max_abs_pcm":peak,"mean_pcm":sum/float64(end-first),"rms_over_initial_ac_amplitude":relative}}
func history_crossings(v []float64,first,end int)map[string]interface{}{points:=[]float64{};for n:=first;n<end-1;n++{a,b:=v[n],v[n+1];if a<=0&&b>0{points=append(points,float64(n)-a/(b-a))}};intervals:=[]float64{};for i:=1;i<len(points);i++{intervals=append(intervals,points[i]-points[i-1])};var median *float64;state:="unresolved_fewer_than_three_raw_zero_rises";if len(points)>=3{sorted:=append([]float64{},intervals...);sort.Float64s(sorted);m:=sorted[len(sorted)/2];if len(sorted)%2==0{m=(m+sorted[len(sorted)/2-1])/2};median=&m;state="raw_zero_rising_intervals_observed_not_frequency_proof"};return map[string]interface{}{"state":state,"first":first,"end_exclusive":end,"threshold_pcm":0,"rising_crossings":points,"intervals_recorded_samples":intervals,"median_interval_recorded_samples":median}}
func history_frequency(v []float64,w history_interval)(map[string]interface{},error){free,err:=fit_free_sine(v,w.First,w.End);if err!=nil{return nil,err};return map[string]interface{}{"free_frequency":free,"raw_zero_crossings":history_crossings(v,w.First,w.End)},nil}
func history_markers(left []float64)[]history_interval{markers:=[]history_interval{};for n:=0;n<len(left);{if left[n]!=0{n++;continue};first:=n;for n<len(left)&&left[n]==0{n++};if n-first>=256{markers=append(markers,history_interval{first,n})}};return markers}
func(job *history_job)analyze()(map[string]interface{},error){p:=history_profiles[job.profile];result:=map[string]interface{}{"version":history_version,"method_sha256":history_method_sha,"profile":job.profile,"contributors":p[0],"middle_tl":p[1],"source_id":job.timing.Source,"provenance":job.binding,"timing":job.timing,"state":"geometry_unresolved","interpretation":"Continuous public-output observations only; no real quantizer q, chip tolerance, conformance test, high-region fit, per-operator correction or proof of common TL scaling.","raw_right":history_stats(job.right,0,len(job.right)),"raw_left":history_stats(job.left,0,len(job.left))};markers:=history_markers(job.left);result["markers"]=markers;if len(markers)!=2{result["geometry_reason"]="requires_exactly_two_observed_zero_runs_at_least256";return result,nil};windows:=[]history_interval{{128,markers[0].First-128},{markers[0].End+128,markers[1].First-128},{max(markers[1].End+128,job.timing.Start),len(job.right)}};result["interiors"]=windows;for _,w:=range windows{if w.End-w.First<1536{result["geometry_reason"]="each_supported_interior_requires1536_samples";return result,nil}};low,err:=history_fit_fixed(job.right,windows[0].First,windows[0].First+1024);if err!=nil{return nil,err};result["initial_low_fit"]=&low;result["initial_low_holdout"]=history_residual(job.right,low.End,low.End+512,low);result["return_against_initial_prediction"]=history_residual(job.right,windows[2].First,windows[2].First+1536,low);ret,err:=history_fit_fixed(job.right,windows[2].First,windows[2].First+1024);if err!=nil{return nil,err};result["return_diagnostic_fit"]=&ret;result["return_own_holdout_diagnostic"]=history_residual(job.right,ret.End,ret.End+512,ret);result["return_transfer_from_initial"]=history_transfer(low,ret);frequency:=map[string]interface{}{};for _,item:=range []struct{name string;window history_interval}{{"initial_low",windows[0]},{"return",windows[2]}}{value,err:=history_frequency(job.right,item.window);if err!=nil{return nil,err};frequency[item.name]=value};result["middle_raw"]=history_stats(job.right,windows[1].First,windows[1].End);allowed:=p[0]==1||p[1]!=0;result["middle_fit_allowed"]=allowed;if allowed{mid,err:=history_fit_fixed(job.right,windows[1].First,windows[1].First+1024);if err!=nil{return nil,err};result["middle_diagnostic_fit"]=&mid;result["middle_own_holdout_diagnostic"]=history_residual(job.right,mid.End,mid.End+512,mid);result["middle_transfer_from_initial"]=history_transfer(low,mid);f,err:=history_frequency(job.right,windows[1]);if err!=nil{return nil,err};frequency["middle"]=f}else{result["middle_state"]="aggregate_TL0_not_fitted_or_free_frequency_scored"};if p[1]==32{f,err:=history_frequency(job.right,history_interval{0,len(job.right)});if err!=nil{return nil,err};frequency["whole_right_held_low_noop_only"]=f};result["frequency_diagnostics"]=frequency;result["state"]="geometry_observed_analysis_descriptive";return result,nil}
func history_wrap(x float64)float64{return math.Atan2(math.Sin(x),math.Cos(x))}
func history_transfer(low,middle history_fit)map[string]interface{}{var gain,phase *float64;if low.Amplitude>0&&middle.Amplitude>0{g:=middle.Amplitude/low.Amplitude;gain=&g;if low.Phase!=nil&&middle.Phase!=nil{p:=history_wrap(*middle.Phase-*low.Phase);phase=&p}};return map[string]interface{}{"amplitude_gain":gain,"phase_delta_cos_sin_radians":phase,"dc_delta_pcm":middle.Beta[2]-low.Beta[2],"interpretation":"descriptive fixed-frequency transfer; no scalar-response proof or pass band"}}
